// Normalize Inputs from Form Submission, Webhook, or Canvas Manual Trigger
const items = $input.all();
const rawItem = items[0]?.json || {};
const body = rawItem.body || {};
const query = rawItem.query || {};

// Detect Trigger Source
let triggerSource = 'manual';
if (rawItem.headers || rawItem.query || (body && Object.keys(body).length > 0 && !rawItem['Post Text'] && !rawItem['field-0'])) {
  triggerSource = 'webhook';
} else if (rawItem.submittedAt || rawItem['Post Text'] || rawItem['field-0']) {
  triggerSource = 'form';
}

// 1. Resolve Execution Mode (dry_run vs live)
const rawMode = (
  rawItem['Execution Mode'] ||
  rawItem.mode ||
  body.mode ||
  body['Execution Mode'] ||
  query.mode ||
  ''
).toString().toLowerCase();

let dryRun = false;
if (
  rawItem.dry_run === true ||
  rawItem.dry_run === 'true' ||
  body.dry_run === true ||
  body.dry_run === 'true' ||
  query.dry_run === 'true' ||
  rawMode.includes('dry') ||
  rawMode.includes('simulation') ||
  rawMode.includes('preview')
) {
  dryRun = true;
}

// 2. Resolve Post Text
const postText = (
  rawItem['Post Text'] ||
  rawItem.post_text ||
  rawItem.text ||
  rawItem.content ||
  rawItem['field-0'] ||
  body['Post Text'] ||
  body.post_text ||
  body.text ||
  body.content ||
  query.text ||
  'Automated update from AI Social Media Publisher.'
).toString().trim();

// 3. Resolve Target Platforms (both, x, linkedin)
const rawPlatforms = (
  rawItem['Target Platforms'] ||
  rawItem.target_platforms ||
  rawItem.platforms ||
  rawItem.platform ||
  rawItem['field-1'] ||
  body['Target Platforms'] ||
  body.platforms ||
  body.platform ||
  query.platform ||
  'both'
).toString().toLowerCase();

let postToX = false;
let postToLinkedIn = false;

if (rawPlatforms.includes('both') || rawPlatforms === 'all') {
  postToX = true;
  postToLinkedIn = true;
} else if (rawPlatforms.includes('x') || rawPlatforms.includes('twitter')) {
  postToX = true;
} else if (rawPlatforms.includes('linkedin')) {
  postToLinkedIn = true;
} else {
  postToX = true;
  postToLinkedIn = true;
}

// 4. Resolve Media Type & Links
const rawMediaType = (
  rawItem['Media Type'] ||
  rawItem.media_type ||
  rawItem['field-2'] ||
  body['Media Type'] ||
  body.media_type ||
  'Text Only'
).toString().toUpperCase();

let mediaType = 'NONE';
if (rawMediaType.includes('IMAGE') || rawMediaType.includes('PHOTO')) {
  mediaType = 'IMAGE';
} else if (rawMediaType.includes('VIDEO')) {
  mediaType = 'VIDEO';
} else if (rawMediaType.includes('ARTICLE') || rawMediaType.includes('LINK')) {
  mediaType = 'ARTICLE';
}

const mediaUrl = (
  rawItem['Media URL (Image or Video Direct Link)'] ||
  rawItem.media_url ||
  rawItem.image_url ||
  rawItem.video_url ||
  rawItem['field-4'] ||
  body['Media URL'] ||
  body.media_url ||
  body.image_url ||
  body.video_url ||
  query.media_url ||
  ''
).toString().trim();

const articleUrl = (
  rawItem['Article / Link URL'] ||
  rawItem.article_url ||
  rawItem.url ||
  rawItem['field-5'] ||
  body['Article / Link URL'] ||
  body.article_url ||
  body.url ||
  query.url ||
  ''
).toString().trim();

// 5. Resolve Tags / Hashtags
const rawTags = (
  rawItem['Hashtags / Tags'] ||
  rawItem.hashtags ||
  rawItem.tags ||
  rawItem['field-6'] ||
  body['Hashtags / Tags'] ||
  body.hashtags ||
  body.tags ||
  query.tags ||
  ''
).toString().trim();

let cleanTags = [];
if (rawTags) {
  cleanTags = rawTags
    .split(/[,\s]+/)
    .map(t => t.trim())
    .filter(Boolean)
    .map(t => (t.startsWith('#') ? t : '#' + t));
}
const tagsString = cleanTags.join(' ');

// 6. Format Platform-Specific Copy
let xText = postText;
if (tagsString) {
  xText = postText + '\n\n' + tagsString;
}

const xCharCount = xText.length;
const isLongTweet = xCharCount > 280;

let linkedinText = postText;
if (tagsString) {
  linkedinText = postText + '\n\n' + tagsString;
}

// 7. LinkedIn Settings
const rawVisibility = (
  rawItem['LinkedIn Visibility'] ||
  rawItem.linkedin_visibility ||
  rawItem.visibility ||
  rawItem['field-7'] ||
  body['LinkedIn Visibility'] ||
  body.linkedin_visibility ||
  body.visibility ||
  'PUBLIC'
).toString().toUpperCase();

const linkedinVisibility = rawVisibility.includes('CONN') ? 'CONNECTIONS' : 'PUBLIC';

const rawPostAs = (
  rawItem['LinkedIn Post As'] ||
  rawItem.linkedin_post_as ||
  rawItem.post_as ||
  rawItem['field-8'] ||
  body['LinkedIn Post As'] ||
  body.linkedin_post_as ||
  'person'
).toString().toLowerCase();

const linkedinPostAs = rawPostAs.includes('org') ? 'organization' : 'person';

const linkedinOrgUrn = (
  rawItem['LinkedIn Organization URN'] ||
  rawItem.linkedin_organization_urn ||
  rawItem.organization_urn ||
  rawItem['field-9'] ||
  body.organization_urn ||
  ''
).toString().trim();

// 8. X Reply Settings
const rawReplySettings = (
  rawItem['X / Twitter Reply Settings'] ||
  rawItem.x_reply_settings ||
  rawItem.reply_settings ||
  rawItem['field-10'] ||
  body.x_reply_settings ||
  'everyone'
).toString();

const xReplySettings = ['following', 'mentionedUsers'].includes(rawReplySettings)
  ? rawReplySettings
  : 'everyone';

// 9. Binary Attachment Check
const binaryData = items[0]?.binary || {};
const hasBinaryMedia = Boolean(binaryData.data || binaryData.file || Object.keys(binaryData).length > 0);
const needsMediaDownload = (mediaType === 'IMAGE' || mediaType === 'VIDEO') && Boolean(mediaUrl) && !hasBinaryMedia;

const outputItem = {
  json: {
    trigger_source: triggerSource,
    dry_run: dryRun,
    post_text: postText,
    platforms_requested: rawPlatforms,
    post_to_x: postToX,
    post_to_linkedin: postToLinkedIn,
    media_type: mediaType,
    media_url: mediaUrl,
    article_url: articleUrl,
    hashtags: cleanTags,
    tags_string: tagsString,
    x_text: xText,
    x_char_count: xCharCount,
    is_long_tweet: isLongTweet,
    x_reply_settings: xReplySettings,
    linkedin_text: linkedinText,
    linkedin_visibility: linkedinVisibility,
    linkedin_post_as: linkedinPostAs,
    linkedin_organization_urn: linkedinOrgUrn,
    needs_media_download: needsMediaDownload,
    has_binary_media: hasBinaryMedia,
    created_at: new Date().toISOString()
  }
};

if (hasBinaryMedia) {
  outputItem.binary = binaryData;
}

return [outputItem];

// Ensure binary property is consistently accessible as 'data'
const items = $input.all();
const item = items[0] || { json: {} };
const binary = item.binary || {};

let normalizedBinary = {};
const keys = Object.keys(binary);
if (keys.length > 0) {
  const primaryKey = keys.includes('data') ? 'data' : keys[0];
  normalizedBinary['data'] = binary[primaryKey];
}

return [{
  json: {
    ...item.json,
    has_binary_data: Object.keys(normalizedBinary).length > 0
  },
  ...(Object.keys(normalizedBinary).length > 0 ? { binary: normalizedBinary } : {})
}];

// Generate realistic simulated execution results for Dry Run mode
const item = $input.first()?.json || {};

const fakeTweetId = '183' + Math.floor(100000000000000 + Math.random() * 900000000000000);
const fakeLinkedinUrn = 'urn:li:share:7' + Math.floor(100000000000000000 + Math.random() * 900000000000000000);

let xSim = null;
if (item.post_to_x) {
  xSim = {
    attempted: true,
    simulated: true,
    success: true,
    tweet_id: fakeTweetId,
    tweet_url: 'https://twitter.com/i/web/status/' + fakeTweetId,
    text: item.x_text,
    char_count: item.x_char_count,
    is_long_tweet: item.is_long_tweet,
    reply_settings: item.x_reply_settings,
    media_attached: item.media_type !== 'NONE' ? item.media_type : null
  };
}

let liSim = null;
if (item.post_to_linkedin) {
  liSim = {
    attempted: true,
    simulated: true,
    success: true,
    post_urn: fakeLinkedinUrn,
    post_url: 'https://www.linkedin.com/feed/update/' + fakeLinkedinUrn,
    text: item.linkedin_text,
    visibility: item.linkedin_visibility,
    post_as: item.linkedin_post_as,
    media_category: item.media_type
  };
}

return [{
  json: {
    status: "success (simulation)",
    mode: "DRY_RUN",
    trigger_source: item.trigger_source || 'manual',
    timestamp: new Date().toISOString(),
    platforms: {
      x: xSim,
      linkedin: liSim
    },
    post_summary: {
      text: item.post_text,
      hashtags: item.hashtags || [],
      media_type: item.media_type,
      media_url: item.media_url || null,
      article_url: item.article_url || null
    },
    message: "Dry run completed successfully! All post validations, hashtag normalization, media download checks, and platform rules passed."
  }
}];

// Route LinkedIn posting by media category
const item = $input.first()?.json || {};
const mediaType = (item.media_type || 'NONE').toUpperCase();

let route = 'text';
if (mediaType === 'IMAGE') route = 'image';
else if (mediaType === 'ARTICLE') route = 'article';
else if (mediaType === 'VIDEO') route = 'video';

return [{
  json: {
    ...item,
    linkedin_route: route
  }
}];

// Aggregate Execution Results Across Platforms
const items = $input.all();
const baseInfo = $('Standardize Media Binary').first()?.json || {};

// If coming from Simulation node, pass simulated output directly
const simOutput = $('Simulate Platform Responses').first()?.json;
if (simOutput && simOutput.mode === 'DRY_RUN') {
  return [{ json: { ...simOutput, trigger_source: baseInfo.trigger_source || simOutput.trigger_source || 'manual' } }];
}

// 1. Inspect X (Twitter) Results
let xResult = { attempted: baseInfo.post_to_x || false, success: false };
if (baseInfo.post_to_x) {
  try {
    const textTweetNode = $('Create Text Tweet (X)').first()?.json;
    const mediaTweetNode = $('Create Tweet with Media (X)').first()?.json;
    const tweetData = textTweetNode || mediaTweetNode;

    if (tweetData && (tweetData.id || tweetData.data?.id)) {
      const tweetId = tweetData.id || tweetData.data?.id;
      xResult.success = true;
      xResult.tweet_id = tweetId;
      xResult.tweet_url = 'https://twitter.com/i/web/status/' + tweetId;
      xResult.text = tweetData.text || tweetData.data?.text || baseInfo.x_text;
    } else if (tweetData?.error) {
      xResult.error = tweetData.error;
    } else {
      xResult.info = "Submitted to X pipeline";
    }
  } catch (e) {
    xResult.error = e.message;
  }
}

// 2. Inspect LinkedIn Results
let linkedinResult = { attempted: baseInfo.post_to_linkedin || false, success: false };
if (baseInfo.post_to_linkedin) {
  try {
    const textNode = $('Share Text Post (LinkedIn)').first()?.json;
    const imgNode = $('Share Image Post (LinkedIn)').first()?.json;
    const artNode = $('Share Article Link (LinkedIn)').first()?.json;
    const videoRegNode = $('Register Video Upload (LinkedIn API)').first()?.json;

    const liData = textNode || imgNode || artNode || videoRegNode;
    if (liData && (liData.id || liData.urn || liData.value?.asset)) {
      const postUrn = liData.id || liData.urn || liData.value?.asset;
      linkedinResult.success = true;
      linkedinResult.post_urn = postUrn;
      linkedinResult.post_url = 'https://www.linkedin.com/feed/update/' + postUrn;
      linkedinResult.visibility = baseInfo.linkedin_visibility || 'PUBLIC';
    } else if (liData?.error) {
      linkedinResult.error = liData.error;
    } else {
      linkedinResult.info = "Submitted to LinkedIn pipeline";
    }
  } catch (e) {
    linkedinResult.error = e.message;
  }
}

// 3. Determine Overall Status
let overallStatus = 'success';
if (xResult.attempted && !xResult.success && linkedinResult.attempted && !linkedinResult.success) {
  overallStatus = 'failed';
} else if ((xResult.attempted && !xResult.success) || (linkedinResult.attempted && !linkedinResult.success)) {
  overallStatus = 'partial_success';
}

const responsePayload = {
  status: overallStatus,
  mode: "LIVE",
  trigger_source: baseInfo.trigger_source || 'manual',
  timestamp: new Date().toISOString(),
  platforms: {
    x: xResult,
    linkedin: linkedinResult
  },
  post_summary: {
    text: baseInfo.post_text,
    hashtags: baseInfo.hashtags || [],
    media_type: baseInfo.media_type,
    media_url: baseInfo.media_url || null,
    article_url: baseInfo.article_url || null
  }
};

return [{
  json: responsePayload
}];
